// PLOT-01: the chart's numbers against values GENERATED BY R (the helpers in
// Projects/R/Time_Series_Plotting), not against values copied from this port.
// Regenerate the fixture with test/fixtures/rReference/generate_chart_reference.R
// whenever helpers_core.R or helpers_echarts.R changes; chartReference.json
// records the sha256 of both so a stale fixture is detectable (see the last test).
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { existsSync, readFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import {
  huePalette,
  padValueRange,
  padTimeRange,
  evenBreaks,
  axisDateLabel,
  finiteExtent,
  seriesShape,
} from '../src/chartSpec';

const reference = JSON.parse(
  readFileSync(resolve(__dirname, '../../test/fixtures/rReference/chartReference.json'), 'utf8')
);

const near = (actual: number, expected: number, what: string) =>
  assert.ok(
    Math.abs(actual - expected) <= 1e-12 * Math.max(1, Math.abs(expected)),
    `${what}: ${actual} vs R ${expected}`
  );

test('hue palette equals scales::hue_pal() for 1 to 60 series', () => {
  assert.equal(reference.palette.length, 60);
  for (let n = 1; n <= 60; n += 1) assert.deepEqual(huePalette(n), reference.palette[n - 1], `n = ${n}`);
});

test('a lone series is R salmon, not the old navy, and the palette depends on the count', () => {
  assert.deepEqual(huePalette(1), ['#F8766D']);
  assert.deepEqual(huePalette(2), ['#F8766D', '#00BFC4']);
  assert.deepEqual(huePalette(3), ['#F8766D', '#00BA38', '#619CFF']);
  assert.notEqual(huePalette(3)[1], huePalette(4)[1]);
});

test('hue palette refuses a count that is not a positive integer', () => {
  for (const bad of [0, -1, 1.5, Number.NaN, Number.POSITIVE_INFINITY]) assert.deepEqual(huePalette(bad), []);
});

test('y axis padding matches compute_echarts_y_range, including the degenerate cases', () => {
  for (const c of reference.y_range) {
    const extent = finiteExtent(c.values)!;
    const got = padValueRange(extent);
    near(got.min, c.range[0], `min of ${c.values}`);
    near(got.max, c.range[1], `max of ${c.values}`);
  }
});

test('y ticks match get_forced_breaks with no forced values', () => {
  for (const c of reference.y_breaks) {
    const got = evenBreaks(c.lo, c.hi, c.count);
    assert.equal(got.length, c.breaks.length, `count for ${c.lo}..${c.hi}`);
    got.forEach((v, i) => near(v, c.breaks[i], `break ${i} of ${c.lo}..${c.hi}`));
  }
});

test('x axis padding is compute_echarts_x_range up to its whole-day formatting', () => {
  // R formats the padded Date, which drops the fraction of a day; the viewer keeps
  // the milliseconds (an intentional difference), so compare on the UTC day.
  const day = (ms: number) => new Date(ms).toISOString().slice(0, 10);
  for (const c of reference.x_range) {
    const got = padTimeRange({ lo: Date.parse(c.start), hi: Date.parse(c.end) });
    assert.equal(day(got.min), c.min, `start ${c.start}`);
    assert.equal(day(got.max), c.max, `end ${c.end}`);
  }
});

test('quarterly, semiannual and weekly tick labels equal make_label_fn', () => {
  for (const group of reference.labels) {
    group.dates.forEach((date: string, i: number) =>
      assert.equal(axisDateLabel(Date.parse(date), group.type), group.labels[i], `${group.type} ${date}`)
    );
  }
});

test('line width, point size and the grid margins are the helpers_echarts.R numbers', () => {
  const style = reference.style;
  assert.equal(seriesShape('line', '#000').lineStyle?.width, style.line_width);
  assert.equal(seriesShape('scatter', '#000').symbolSize, style.scatter_size);
  assert.equal(style.axis_line_width, 1.5);
  assert.equal(style.axis_font_size, 10);
  assert.equal(style.legend_font_size, 11);
  assert.equal(style.y_ticks, 8);
});

test('the fixture records the R helpers it came from', () => {
  assert.match(reference.helpers_core_sha256, /^[0-9a-f]{64}$/);
  assert.match(reference.helpers_echarts_sha256, /^[0-9a-f]{64}$/);
  assert.equal(reference.scales_version, '1.4.0');
});

// Opt-in drift gate: DFV_R_HELPERS_DIR=<.../Time_Series_Plotting> npm test. A changed
// helper means the palette/range/label expectations above need a human review and a
// regenerated fixture -- it is never an automatic pass.
test('the R helpers have not changed since the fixture was generated', { skip: !process.env.DFV_R_HELPERS_DIR }, () => {
  const dir = process.env.DFV_R_HELPERS_DIR!;
  for (const [file, key] of [
    ['helpers_core.R', 'helpers_core_sha256'],
    ['helpers_echarts.R', 'helpers_echarts_sha256'],
  ]) {
    const path = join(dir, 'helpers', file);
    assert.ok(existsSync(path), path);
    assert.equal(createHash('sha256').update(readFileSync(path)).digest('hex'), reference[key], `${file} drifted`);
  }
});
